$results = @()
# Hole alle echten Benutzer-SIDs (beginnen mit S-1-5-21, schließt Systemkonten aus)
$userHives = Get-ChildItem Registry::HKEY_USERS | Where-Object { $_.Name -match 'S-1-5-21-[\d\-]+$' }

foreach ($hive in $userHives) {
    # Extrahiere die reine SID
    $sid = $hive.Name.Replace("HKEY_USERS\", "")
    
    # Übersetze die SID in einen lesbaren Benutzernamen (Domäne\User)
    try {
        $objSID = New-Object System.Security.Principal.SecurityIdentifier($sid)
        $username = $objSID.Translate([System.Security.Principal.NTAccount]).Value
    } catch {
        $username = "Konnte nicht aufgelöst werden ($sid)"
    }

    # Definiere den Pfad zum Drucker-Schlüssel des jeweiligen Users
    $regPath = "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows NT\CurrentVersion\Windows"
    
    try {
        # Der Wert in "Device" sieht so aus: "Druckername,winspool,Ne00:" - wir brauchen nur den ersten Teil
        $device = Get-ItemPropertyValue -Path $regPath -Name "Device" -ErrorAction Stop
        $defaultPrinter = $device.Split(',')[0]
        
        $results += [PSCustomObject]@{
            Benutzer       = $username
            Standarddrucker = $defaultPrinter
        }
    } catch {
        # Wird ausgelöst, wenn der User keinen Standarddrucker festgelegt hat
        $results += [PSCustomObject]@{
            Benutzer       = $username
            Standarddrucker = "Kein Standarddrucker definiert"
        }
    }
}

# Ausgabe formatieren
$results | Format-Table -AutoSize

Get-Mailbox -RecipientTypeDetails UserMailbox | ForEach-Object {
    Set-MailboxRegionalConfiguration -Identity $_.PrimarySmtpAddress -Language de-DE -DateFormat "dd.MM.yyyy" -TimeFormat "HH:mm" -TimeZone "W. Europe Standard Time"
}



Get-Mailbox -RecipientTypeDetails UserMailbox | ForEach-Object {
    Set-MailboxRegionalConfiguration -Identity $_.PrimarySmtpAddress -Language de-DE -LocalizeDefaultFolderName
}
